          <div>
            <div class="pdu-sub">Breaker Type</div>
            <select id="pdu-breaker" class="pdu-sel">
              <option value="none" ${r.breaker===`none`?`selected`:``}>None</option>
              <option value="mcb" ${r.breaker===`mcb`?`selected`:``}>MCB</option>
              <option value="mcb-guarded" ${(r.breaker??`mcb-guarded`)===`mcb-guarded`?`selected`:``}>MCB + Guard</option>
              <option value="hydraulic" ${r.breaker===`hydraulic`?`selected`:``}>Hydraulic</option>
              <option value="electronic" ${r.breaker===`electronic`?`selected`:``}>Electronic</option>
              <option value="locking" ${r.breaker===`locking`?`selected`:``}>Locking</option>
            </select>
          </div>
          <div>
